import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
ORDER_ID = os.environ["PRODUCTION_ORDER_ID"]
HISTORICAL_REPORT_ID = os.environ["HISTORICAL_REPORT_ID"]

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if os.getenv("API_TOKEN"):
    session.headers["Authorization"] = f"Bearer {os.environ['API_TOKEN']}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.status_code == 204 or not response.content:
        return None
    return response.json()


order_status = request("GET", f"/production/orders/{ORDER_ID}/status")
deliveries = request("GET", "/deliveries")

if isinstance(deliveries, dict):
    deliveries = deliveries.get("deliveries", [])

associated_deliveries = [
    delivery for delivery in deliveries
    if str(delivery.get("productionOrderId", delivery.get("orderId", ""))) == str(ORDER_ID)
]

delivery_details = []
for delivery in associated_deliveries:
    delivery_id = delivery.get("id")
    if delivery_id is not None:
        details = request("GET", f"/deliveries/{delivery_id}")
        delivery_details.append(details or delivery)
    else:
        delivery_details.append(delivery)

incomplete_or_unnecessary = []
for delivery in delivery_details:
    status = str(delivery.get("status", "")).lower()
    necessary = delivery.get("necessary", delivery.get("required", True))
    if status in {"incomplete", "cancelled", "failed", "unneeded", "unnecessary"} or necessary is False:
        incomplete_or_unnecessary.append(delivery)

deleted_deliveries = []
for delivery in incomplete_or_unnecessary:
    delivery_id = delivery.get("id")
    if delivery_id is not None:
        request("DELETE", f"/deliveries/{delivery_id}")
        deleted_deliveries.append(delivery_id)

incidents = []
for delivery in delivery_details:
    incident = delivery.get("safetyIncident")
    if incident:
        incidents.append(incident if isinstance(incident, dict) else {"description": str(incident)})

for incident in incidents:
    request("POST", "/incident-report", json=incident)

mineral_distribution = request("GET", "/mineral-distribution")
yield_parameters = {
    "productionOrderId": ORDER_ID,
    "orderStatus": order_status,
    "affectedAreas": mineral_distribution,
    "safetyIncidents": incidents,
}
updated_yield = request("POST", "/yield-calculation", json=yield_parameters)

historical_analytics = request("GET", f"/analytics/{HISTORICAL_REPORT_ID}")

result = {
    "productionOrderStatus": order_status,
    "associatedDeliveries": delivery_details,
    "deletedDeliveryIds": deleted_deliveries,
    "reportedSafetyIncidents": incidents,
    "mineralDistribution": mineral_distribution,
    "updatedYieldPrediction": updated_yield,
    "historicalAnalytics": historical_analytics,
}
print(result)

